use vstd::prelude::*;

verus! {
    fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> (result: Vec<i8>)
        requires
            true,
        ensures
            numbers.len() == 0 ==> result.len() == 0 &&
            numbers.len() == 1 ==> result.len() == 1 && result[0] == numbers[0] &&
            numbers.len() > 1 ==> result.len() == 2 * numbers.len() - 1 &&
            forall |i: nat| (i < numbers.len() as nat) ==> result[2 * i as usize] == numbers[i as usize] &&
            forall |j: nat| (j < (numbers.len() as nat - 1)) ==> result[2 * j as usize + 1] == delimiter
    {
        let n = numbers.len();
        let mut result = Vec::with_capacity(if n == 0 { 0 } else { 2 * n - 1 });
        
        if n == 0 {
            return result; // Return empty vector
        } else if n == 1 {
            result.push(numbers[0]); // Return the single element
            return result;
        }

        // Fill the result vector for n > 1
        let mut idx = 0;
        while idx < n
            invariant
                idx <= n,
                result.len() == 2 * idx - 1,
                forall |i: nat| (i < idx as nat) ==> result[2 * i as usize] == numbers[i as usize] &&
                forall |j: nat| (j < (idx as nat - 1)) ==> result[2 * j as usize + 1] == delimiter,
            decreases n - idx,
        {
            result.push(numbers[idx as usize]); // Add the number
            if idx < n - 1 {
                result.push(delimiter); // Add the delimiter if not the last number
            }
            idx = idx + 1;
        }
        
        result
    }
}

